class SubclassesDataset(torchvision.datasets.ImageFolder):
    def __init__(self, dat:torchvision.datasets.ImageFolder, selected_class_indices):
        super().__init__(dat.root, dat.transform, dat.target_transform, dat.loader)
        
        n_classes = len(selected_class_indices)
        selected_names = [self.classes[i] for i in selected_class_indices]
        map_idx = -np.ones(len(self.classes), dtype = np.int64)
        map_idx[selected_class_indices] = np.arange(len(selected_class_indices)) # old index to new index map
        self.class_to_idx = dict( (selected_names[i],i) for i in range(len(selected_names)) )
        self.imgs = [(path, map_idx[idx]) for path, idx in self.imgs if idx in selected_class_indices]
        self.classes = selected_names
        self.samples = self.imgs
        self.targets = [s[1] for s in self.samples]
        for (d, t) in self.samples:
            assert(t >= 0)
            assert(t < n_classes)
            assert(type(t) == np.int64)
            break
        print('Dataset size:' + str(len(self)))
    
    
