def map_path(path):
    # Hook to redirect the dataset cache (.beton files) to a fast local disk if
    # desired; identity by default. Override to taste, e.g. by replacing the
    # dataset root with a local scratch path.
    return path

def get_dataset(path, write_mode='smart', max_resolution = None, data_variant = '',  compress_probability=None, jpeg_quality = 90, num_workers = 8, chunk_size=100, subclasses=None):
    localpath = map_path(path) # save DB on the local drive
    if data_variant == '':
        write_path = localpath + f'-{max_resolution}.beton'
    else:
        write_path = localpath + data_variant + '.beton'
    print(f'datast: {write_path}')
    if not os.path.exists(write_path):
        force_path(write_path, wpublic = True)
        #
        my_dataset = torchvision.datasets.ImageFolder(path)
        if subclasses is not None:
            my_dataset = SubclassesDataset(my_dataset, subclasses)
        #
        writer = DatasetWriter(write_path, {
            'image': RGBImageField(write_mode=write_mode,
                                max_resolution=max_resolution,
                                compress_probability=compress_probability,
                                jpeg_quality=jpeg_quality),
            'label': IntField(),
        }, num_workers=num_workers)
        writer.from_indexed_dataset(my_dataset, chunksize=chunk_size)
        os.chmod(write_path, 0o666) # "rw for all, in case we will need to cleanup / update"
    return write_path

