def create_net(o, print_info=False):
    torch.manual_seed(o.seed) # network initialization seed    
    try: 
        cls = globals()[o.net_name]
    except KeyError:
        return arch_imagenet.create_net(o, print_info=print_info)
    net = cls(o, **o.net_args, print_info=print_info).to(device.dev)
    if print_info:
        print(net)
    return net
